/**
 * @name Path traversal in file operations
 * @description Using user-controlled input in file path operations without validation can allow path traversal
 * @kind path-problem
 * @problem.severity error
 * @id py/path-traversal
 * @tags security
 *        external/cwe/cwe-022
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.Concepts
import semmle.python.ApiGraphs

module PathTraversalConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    // Function parameters as potential user input
    source instanceof DataFlow::ParameterNode or
    // Attribute access that might come from external data
    exists(DataFlow::AttrRead attr |
      source = attr and
      attr.getAttributeName() in ["name", "path", "filename", "file"]
    )
  }

  predicate isSink(DataFlow::Node sink) {
    // File system access operations
    exists(FileSystemAccess fsa |
      sink = fsa.getAPathArgument()
    ) or
    // Path operations
    exists(DataFlow::CallCfgNode call |
      sink = call.getArg(0) and
      (
        call = API::moduleImport("pathlib").getMember("Path").getACall() or
        call = API::moduleImport("os").getMember("path").getMember(["join", "exists", "isfile", "isdir"]).getACall() or
        call = API::builtin("open").getACall()
      )
    )
  }
}

module PathTraversalFlow = TaintTracking::Global<PathTraversalConfig>;
import PathTraversalFlow::PathGraph

from PathTraversalFlow::PathNode source, PathTraversalFlow::PathNode sink
where PathTraversalFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Potential path traversal from $@.", source.getNode(), "user-controlled input"
